48	                .isInstanceOfSatisfying(ApiException.class, ex -> {
49	                    assertThat(ex.getStatus()).isEqualTo(HttpStatus.CONFLICT);
50	                    assertThat(ex.getErrorCode()).isEqualTo("IDEMPOTENCY_CONFLICT");
51	                });
52	
53	        // 仅有首次一张申请单
54	        Integer count = jdbc.queryForObject(
55	                "SELECT COUNT(*) FROM harvest_application WHERE request_id='idem-app-2'", Integer.class);
