74	        assertThatThrownBy(() -> service.apply(
75	                new ApplyRequest("idem-app-3", "OP-I", "SP-005", "PINUS_MASSONIANA", "MAIN", new BigDecimal("10.00"))))
76	                .isInstanceOfSatisfying(ApiException.class, ex ->
77	                        assertThat(ex.getErrorCode()).isEqualTo("PROTECTED_ZONE_FORBIDDEN"));
78	
79	        // 同键异参仍 409，不允许借同键“改道”
80	        assertThatThrownBy(() -> service.apply(
81	                new ApplyRequest("idem-app-3", "OP-I", "SP-001", "PINUS_MASSONIANA", "MAIN", new BigDecimal("10.00"))))
82	                .isInstanceOfSatisfying(ApiException.class, ex ->
83	                        assertThat(ex.getErrorCode()).isEqualTo("IDEMPOTENCY_CONFLICT"));
