92	        LicenseView replay = service.issue(new IssueRequest("idem-flow-issue", app.id()));
93	        assertThat(replay.id()).isEqualTo(first.id());
94	        // 仅一笔占用台账
95	        Integer holds = jdbc.queryForObject(
96	                "SELECT COUNT(*) FROM quota_ledger WHERE action='HOLD'", Integer.class);
97	        assertThat(holds).isOne();
98	
99	        clock.setToday(LocalDate.of(2026, 4, 1));
100	        var confirmed = service.confirm(new ConfirmRequest("idem-flow-confirm", first.id()));
101	        var confirmReplay = service.confirm(new ConfirmRequest("idem-flow-confirm", first.id()));
102	        assertThat(confirmReplay.id()).isEqualTo(confirmed.id());
103	        assertThat(confirmReplay.status()).isEqualTo("HARVESTED");
104	    }
