2	
3	import java.sql.Date;
4	import java.time.LocalDate;
5	
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.stereotype.Repository;
9	
10	import com.example.starter.forestry.domain.IdempotentOperation;
11	import com.example.starter.forestry.po.IdempotentRecordPO;
12	
13	/**
14	 * 幂等请求记录仓储。记录以 (operation, requestId) 为唯一键：
15	 * PENDING 表示首次请求处理中（并发同键等待），DONE 保存首次结果快照（含业务拒绝）。
16	 */
17	@Repository
18	public class IdempotencyRepository {
19	
20	    private final JdbcTemplate jdbc;
21	
22	    public IdempotencyRepository(JdbcTemplate jdbc) {
23	        this.jdbc = jdbc;
24	    }
25	
26	    /**
27	     * 尝试占位为 PENDING。
28	     *
29	     * @return true 占位成功（当前请求为首处理者）；false 已存在同键记录
30	     */
31	    public boolean tryInsertPending(IdempotentOperation operation, String requestId,
32	                                    String fingerprint, LocalDate today) {
33	        try {
34	            jdbc.update("""
35	                    INSERT INTO idempotent_request
36	                        (operation, request_id, fingerprint, status, response_type, response_status,
37	                         ref_id, response_json, created_date)
38	                    VALUES (?, ?, ?, 'PENDING', NULL, NULL, NULL, NULL, ?)
39	                    """,
40	                    operation.name(), requestId, fingerprint, Date.valueOf(today));
41	            return true;
42	        } catch (DuplicateKeyException e) {
43	            return false;
44	        }
45	    }
46	
47	    /**
48	     * 查询同键记录，不存在返回 null。
49	     */
50	    public IdempotentRecordPO find(IdempotentOperation operation, String requestId) {
51	        var rows = jdbc.query("""
52	                        SELECT operation, request_id, fingerprint, status, response_type, response_status,
53	                               ref_id, response_json, created_date
54	                        FROM idempotent_request
55	                        WHERE operation = ? AND request_id = ?
56	                        """,
57	                (rs, n) -> new IdempotentRecordPO(
58	                        rs.getString("operation"),
59	                        rs.getString("request_id"),
60	                        rs.getString("fingerprint"),
61	                        rs.getString("status"),
62	                        rs.getString("response_type"),
63	                        rs.getObject("response_status", Integer.class),
64	                        rs.getString("ref_id"),
65	                        rs.getString("response_json"),
66	                        rs.getDate("created_date") == null ? null : rs.getDate("created_date").toLocalDate()),
67	                operation.name(), requestId);
68	        return rows.isEmpty() ? null : rows.get(0);
69	    }
70	
71	    /**
72	     * 首次处理完成：写入结果快照并置 DONE。
73	     *
74	     * @param responseStatus 业务失败时为其 HTTP 状态码；成功时为 null
75	     */
76	    public void markDone(IdempotentOperation operation, String requestId,
77	                         String responseType, Integer responseStatus, String refId, String responseJson) {
78	        jdbc.update("""
79	                        UPDATE idempotent_request
80	                           SET status = 'DONE', response_type = ?, response_status = ?,
81	                               ref_id = ?, response_json = ?
82	                         WHERE operation = ? AND request_id = ? AND status = 'PENDING'
83	                        """,
84	                responseType, responseStatus, refId, responseJson, operation.name(), requestId);
85	    }
86	}
