        // 并发发证在新增株数口径上同样串行校验，只可能一张成功
        var app1 = service.apply(new ApplyRequest("c-t-app1", "OP-C6", "SP-001",
                "PINUS_MASSONIANA", "MAIN", 60, new BigDecimal("30.00")));
